with required(relation_name,column_name)as(values ('tms_users','id'),('tms_users','is_active'),('tms_users','role'),('weekly_message_target_attempts','id'),('weekly_message_target_attempts','dispatch_target_id'),('weekly_message_target_attempts','lease_token'),('weekly_message_target_attempts','lease_owner'),('weekly_message_target_attempts','completed_at_utc'),('weekly_message_target_attempts','attempt_number'),('weekly_message_target_attempts','outcome'),('weekly_message_target_attempts','provider_message_id'),('weekly_message_target_attempts','bounded_provider_receipt_json'),('weekly_message_target_attempts','bounded_error_json'),('weekly_message_target_attempts','result_hash'),('weekly_message_dispatch_targets','id'),('weekly_message_dispatch_targets','dispatch_command_id'),('weekly_message_dispatch_commands','id'),('weekly_message_dispatch_commands','agency_id'),('weekly_message_dispatch_commands','environment')),missing as(select e.* from required e left join pg_namespace n on n.nspname='public'left join pg_class c on c.relnamespace=n.oid and c.relname=e.relation_name left join pg_attribute a on a.attrelid=c.oid and a.attname=e.column_name and a.attnum>0 and not a.attisdropped where a.attname is null)
 select jsonb_build_object('database',current_database(),'missing_required_columns',(select coalesce(jsonb_agg(to_jsonb(m)order by relation_name,column_name),'[]')from missing m),'digest_available',to_regprocedure('extensions.digest(bytea,text)')is not null,'scope','CATALOGUE_ONLY_NOT_FIXTURE_OR_ROLE_PROOF')as contact_discovery_preflight;
